-- Explicações pedagógicas (BE-004) — Marketing Digital difícil lote 2: as perguntas ativas v2#2 a v2#25 do seed dificil_v2 (migration 050) e a 1.ª do dificil_v3 (migration 059).
-- Preenche questions.explanation com o "Por quê?" de cada pergunta (raciocínio e relação entre conceitos, nível difícil, conforme
-- docs/quiz-v2-rodadas-e-feedback.md), já coerente com as alternativas novas da migration 522. Só atualiza perguntas
-- que ainda NÃO têm explicação, então é idempotente e nunca sobrescreve texto já escrito. Não altera perguntas nem
-- alternativas. Se alguma pergunta já não existir, é simplesmente ignorada (nunca falha, para não impedir o arranque
-- do backend: as migrations correm no deploy). O runner já envolve o ficheiro numa transação.

DO $$
DECLARE
  v_updated INTEGER;
BEGIN
  UPDATE questions q
  SET explanation = v.explanation
  FROM (VALUES
    ('seed_marketing_digital_dificil_v2', 'Por que comparar LTV e CAC pode ser útil?', 'Comparar LTV e CAC mede a relação entre o valor que o cliente pode gerar e o custo de o conquistar: se o valor supera o custo, a aquisição tende a compensar. Alcance, tráfego, hospedagem ou treinamento não entram nessa relação.'),
    ('seed_marketing_digital_dificil_v2', 'Uma empresa possui CAC de 500 MZN e estima LTV de 2.000 MZN por cliente. Qual é a relação LTV/CAC?', 'A relação LTV/CAC é o valor do cliente dividido pelo custo de o adquirir: 2.000 ÷ 500 = 4. Significa que cada metical gasto na aquisição tende a gerar 4 de valor ao longo do relacionamento. Costuma-se procurar valores acima de 3, como referência.'),
    ('seed_marketing_digital_dificil_v2', 'Por que a atribuição pode ser complexa?', 'A atribuição é complexa porque um cliente pode interagir com vários canais, como anúncio, email e busca, antes de converter, e fica difícil decidir qual merece o crédito. Se houvesse um único canal, bastaria olhar para ele.'),
    ('seed_marketing_digital_dificil_v2', 'O que é modelo de atribuição de último clique?', 'No modelo de último clique, a conversão é atribuída principalmente ao último ponto de contato antes da compra. É simples, mas ignora os canais anteriores da jornada. O primeiro clique e o modelo linear, que divide o crédito, são outros modelos.'),
    ('seed_marketing_digital_dificil_v2', 'O que é funil de marketing?', 'O funil de marketing representa as etapas pelas quais potenciais clientes podem passar, da descoberta à conversão e ao relacionamento. Serve para ver onde se perde gente. Não é o caminho de anúncios, de equipes nem de produtos.'),
    ('seed_marketing_digital_dificil_v2', 'Por que analisar cada etapa do funil?', 'Analisar cada etapa do funil mostra onde potenciais clientes abandonam o processo, e assim se sabe onde agir primeiro, como melhorar a página de preços. Não se trata de orçamento de anúncios, de fornecedores nem de funcionários.'),
    ('seed_marketing_digital_dificil_v2', 'Um anúncio recebe muitas visualizações, mas poucos cliques. O que pode ser investigado primeiro?', 'Muitas visualizações e poucos cliques indicam que o anúncio aparece mas não convence, então se investiga primeiro a mensagem, o criativo, a oferta e a chamada para ação. Estoque, frete ou dados da empresa só influenciam depois do clique.'),
    ('seed_marketing_digital_dificil_v2', 'Um anúncio possui muitos cliques, mas poucas conversões. Qual hipótese merece investigação?', 'Muitos cliques e poucas conversões indicam que o anúncio atrai, mas algo falha depois do clique; por isso a hipótese está na oferta, na página de destino, no público ou no processo de conversão. Alcance, impressões e aspecto do anúncio já cumpriram o papel, pois geraram cliques.'),
    ('seed_marketing_digital_dificil_v2', 'O que é taxa de abandono?', 'A taxa de abandono é o percentual de usuários que começam um processo, como um carrinho de compras, mas não o concluem. Concluir sem voltar a comprar, não clicar em anúncios ou não responder a emails são outras métricas.'),
    ('seed_marketing_digital_dificil_v2', 'O que é segmentação comportamental?', 'A segmentação comportamental agrupa o público por comportamentos ou interações observáveis, como páginas visitadas ou compras anteriores, e não por quem a pessoa é. Dados demográficos, geográficos ou de pesquisas são outros critérios.'),
    ('seed_marketing_digital_dificil_v2', 'Qual é um risco de segmentar excessivamente uma campanha?', 'Segmentar demais pode deixar o público pequeno demais, o que limita o alcance e a quantidade de dados de que o algoritmo precisa para otimizar. O problema é o público pequeno, e não grande, parecido ou distante demais.'),
    ('seed_marketing_digital_dificil_v2', 'O que é canibalização entre campanhas?', 'Canibalização acontece quando campanhas ou estratégias competem parcialmente pelo mesmo público ou demanda, e uma tira resultados da outra, o que desperdiça verba. Não é repetir orçamento, nem concorrência entre empresas, nem substituir clientes.'),
    ('seed_marketing_digital_dificil_v2', 'O que significa saturação de audiência?', 'Saturação de audiência é quando o mesmo público recebe exposição excessiva a uma comunicação, e a resposta cai. É o contrário de pouca exposição, e não é excesso de verba nem de concorrência.'),
    ('seed_marketing_digital_dificil_v2', 'Por que a frequência de exposição deve ser monitorada em campanhas?', 'A frequência deve ser monitorada porque exposição excessiva pode causar fadiga e reduzir a eficiência da comunicação, já que o público se cansa de ver o mesmo anúncio. Mais exposição não garante mais conversões, e pouca exposição não causa fadiga.'),
    ('seed_marketing_digital_dificil_v2', 'O que é fadiga criativa?', 'Fadiga criativa é a redução do desempenho de um criativo depois de exposição repetida ou perda de novidade: o público já viu e deixa de reagir. A resposta é renovar o criativo. Não é orçamento menor nem equipe menor.'),
    ('seed_marketing_digital_dificil_v2', 'O que é marketing de conteúdo baseado em intenção?', 'Marketing de conteúdo baseado em intenção produz conteúdo alinhado ao que o público busca ou quer resolver, em vez do que a empresa quer vender, do que o concorrente publica ou do que o algoritmo premia.'),
    ('seed_marketing_digital_dificil_v2', 'Por que a intenção de busca é importante no SEO?', 'A intenção de busca ajuda a alinhar o conteúdo com aquilo que o usuário realmente procura, o que aumenta a relevância e tende a favorecer o desempenho. Escolher domínios, copiar concorrentes ou pagar anúncios não faz isso.'),
    ('seed_marketing_digital_dificil_v2', 'O que é palavra-chave de cauda longa?', 'Palavra-chave de cauda longa é uma consulta mais específica e composta por várias palavras, como "tênis de corrida para pé largo". É o oposto da consulta genérica de uma ou duas palavras, e não tem relação com a idade, o preço ou a marca.'),
    ('seed_marketing_digital_dificil_v2', 'Por que palavras-chave de cauda longa podem ser úteis?', 'As palavras-chave de cauda longa podem revelar uma intenção mais específica e, em alguns contextos, menor concorrência, e por isso podem converter melhor. Costumam ter menos volume, e não mais, e ainda exigem conteúdo relevante.'),
    ('seed_marketing_digital_dificil_v2', 'O que é autoridade de domínio em termos gerais de SEO?', 'A autoridade de domínio, em termos gerais, representa a força ou autoridade percebida de um domínio, embora cada ferramenta use métricas próprias. Não é o preço do domínio, a idade do registo nem a velocidade técnica.'),
    ('seed_marketing_digital_dificil_v2', 'Por que links relevantes de outros sites podem ser importantes para SEO?', 'Links relevantes de outros sites podem funcionar como sinais de autoridade ou referência, dependendo da qualidade e do contexto. Não são sinais de velocidade, de segurança nem de popularidade por volume.'),
    ('seed_marketing_digital_dificil_v2', 'O que é taxa de engajamento?', 'A taxa de engajamento relaciona interações, como curtidas e comentários, com uma base de exposição ou audiência, conforme a fórmula escolhida. Custos, conversões e receita relacionam-se com outras métricas, como CPC, taxa de conversão e ROI.'),
    ('seed_marketing_digital_dificil_v2', 'Por que é importante conhecer a fórmula usada para calcular uma métrica de marketing?', 'É importante conhecer a fórmula porque diferentes fórmulas e bases, como alcance, impressões ou seguidores, podem produzir resultados diferentes para a mesma métrica. Sem isso, números parecidos podem não ser comparáveis.'),
    ('seed_marketing_digital_dificil_v2', 'Por que correlação não significa necessariamente causalidade em marketing?', 'Correlação não significa causalidade porque duas variáveis podem variar juntas sem que uma seja necessariamente responsável pela outra: pode haver uma terceira causa ou coincidência. Por isso se usam testes para provar o efeito de uma ação.'),
    ('seed_marketing_digital_dificil_v3', 'Qual é o principal objetivo de uma estratégia de Growth Marketing?', 'O Growth Marketing procura formas escaláveis de crescimento usando dados e experimentação: testa hipóteses, mede e repete o que funciona. Não se limita a publicar nas redes, a anúncios tradicionais ou a ganhar seguidores.')
  ) AS v(source, statement, explanation)
  WHERE q.source = v.source
    AND q.statement = v.statement
    AND q.explanation IS NULL;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RAISE NOTICE 'Explicações Marketing Digital difícil lote 2: as perguntas ativas v2#2 a v2#25 do seed dificil_v2 (migration 050) e a 1.ª do dificil_v3 (migration 059): % pergunta(s) atualizada(s) (esperado: 25).', v_updated;
END $$;
